package main

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"strconv"
)

type scheduleAssignment struct {
	Name   string `json:"name"`
	Worker int    `json:"worker"`
	Start  int    `json:"start"`
	End    int    `json:"end"`
}

func runSchedule(args []string) int {
	fs := flag.NewFlagSet("schedule", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	specPath := fs.String("spec", "", "path to spec file")
	workersStr := fs.String("workers", "", "number of worker lanes")
	format := fs.String("format", "text", "output format: text|json")

	if err := fs.Parse(args); err != nil {
		return 2
	}

	if *specPath == "" {
		fmt.Fprintln(os.Stderr, "error: missing --spec")
		return 2
	}

	workers, ok := parseWorkers(*workersStr)
	if !ok {
		fmt.Fprintln(os.Stderr, "error: bad --workers")
		return 2
	}

	if *format != "text" && *format != "json" {
		fmt.Fprintln(os.Stderr, "error: bad --format")
		return 2
	}

	if len(fs.Args()) > 0 {
		fmt.Fprintf(os.Stderr, "error: unexpected argument: %s\n", fs.Args()[0])
		return 2
	}

	spec, err := loadSpec(*specPath)
	if err != nil {
		printValidationError(err)
		return 2
	}

	assignments, makespan := computeSchedule(spec, workers)
	switch *format {
	case "text":
		os.Stdout.Write(renderScheduleText(makespan, assignments))
	case "json":
		os.Stdout.Write(renderScheduleJSON(workers, makespan, assignments))
	}
	return 0
}

func parseWorkers(s string) (int, bool) {
	if s == "" || s[0] < '1' || s[0] > '9' {
		return 0, false
	}
	for i := 1; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}

	n := 0
	for i := 0; i < len(s); i++ {
		n = n*10 + int(s[i]-'0')
	}
	return n, true
}

func computeSchedule(spec *Spec, workers int) ([]scheduleAssignment, int) {
	levels := computeLevels(spec)
	busyUntil := make([]int, workers)
	endTime := make(map[string]int, len(spec.Jobs))

	assignments := make([]scheduleAssignment, 0, len(spec.Jobs))
	makespan := 0

	for _, names := range levels {
		for _, name := range names {
			job := spec.ByName[name]

			earliest := 0
			for _, dep := range job.Deps {
				if end := endTime[dep]; end > earliest {
					earliest = end
				}
			}

			worker := -1
			for w := 0; w < workers; w++ {
				if busyUntil[w] <= earliest {
					worker = w
					break
				}
				if worker == -1 || busyUntil[w] < busyUntil[worker] {
					worker = w
				}
			}
			if worker == -1 {
				worker = 0
			}
			if busyUntil[worker] > earliest {
				earliest = busyUntil[worker]
			}

			start := earliest
			end := start + 1
			busyUntil[worker] = end
			endTime[name] = end

			assignments = append(assignments, scheduleAssignment{
				Name:   name,
				Worker: worker,
				Start:  start,
				End:    end,
			})

			if end > makespan {
				makespan = end
			}
		}
	}

	return assignments, makespan
}

func renderScheduleText(makespan int, assignments []scheduleAssignment) []byte {
	var b bytes.Buffer
	b.WriteString("makespan=")
	b.WriteString(strconv.Itoa(makespan))
	b.WriteByte('\n')
	for _, a := range assignments {
		b.WriteString(a.Name)
		b.WriteString("\tworker=")
		b.WriteString(strconv.Itoa(a.Worker))
		b.WriteString("\tstart=")
		b.WriteString(strconv.Itoa(a.Start))
		b.WriteString("\tend=")
		b.WriteString(strconv.Itoa(a.End))
		b.WriteByte('\n')
	}
	return b.Bytes()
}

func renderScheduleJSON(workers, makespan int, assignments []scheduleAssignment) []byte {
	var b bytes.Buffer
	b.WriteString(`{"workers":`)
	b.WriteString(strconv.Itoa(workers))
	b.WriteString(`,"makespan":`)
	b.WriteString(strconv.Itoa(makespan))
	b.WriteString(`,"assignments":[`)
	for i, a := range assignments {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"name":"`)
		writeJSONString(&b, a.Name)
		b.WriteString(`","worker":`)
		b.WriteString(strconv.Itoa(a.Worker))
		b.WriteString(`,"start":`)
		b.WriteString(strconv.Itoa(a.Start))
		b.WriteString(`,"end":`)
		b.WriteString(strconv.Itoa(a.End))
		b.WriteByte('}')
	}
	b.WriteString(`]}`)
	b.WriteByte('\n')
	return b.Bytes()
}
